body_text:
`sorted()` calls `slice::sort_by` with a comparator that returns `Ordering::Equal` whenever two elements are not comparable, intending to surface the comparison error *after* the sort. Returning `Equal` for incomparable pairs makes the comparator violate the total-order contract. Since Rust 1.81 the standard library's stable sort detects an inconsistent comparator and **panics** (`core/src/slice/sort/shared/smallsort.rs`: `user-provided comparison function does not correctly implement a total order`), which happens before the deferred error check is ever reached.

### Reproducer

```python
sorted([5, 4, 3, 2, 1, 0, len, 9, 8, 7, 6, 5, 4, 3, 2, 1, 0, len, 9, 8, 7, 6])
```

`len` (a builtin) is not comparable to the integers. The list must be long enough (> ~20 elements) that the sort takes the quicksort/driftsort path rather than the small-input insertion sort, short lists do not trip the check. Mixed incomparable types in general trigger it, e.g. ints + a function + a string.

Thread panics with `user-provided comparison function does not correctly implement a total order`; with `panic = "abort"` the process aborts.

### Root cause

`starlark-rust/starlark/src/stdlib/funcs/other.rs:356-373`:

```rust
let mut compare_ok = Ok(());
it.sort_by(|x: &(Value, Value), y: &(Value, Value)| {
    let ord_or_err = if reverse { x.1.compare(y.1).map(Ordering::reverse) }
                     else        { x.1.compare(y.1) };
    match ord_or_err {
        Ok(r) => r,
        Err(e) => { compare_ok = Err(e); Ordering::Equal /* "does not matter" */ }
    }
});
compare_ok?;   // never reached if sort_by already panicked
```

`Ordering::Equal` for an incomparable pair breaks transitivity: in the example `len` compares `Equal` to both `0` and `9`, yet `0 < 9`. `std`'s sort detects this and panics.

### Proof of Concept

Runs in the release profile (reproduces in stock release):

```bash
set -uo pipefail

BUCK2="${BUCK2:-${1:-}}"
if [ -z "$BUCK2" ]; then
  d="$PWD"
  while [ "$d" != / ]; do
    [ -f "$d/starlark-rust/starlark/Cargo.toml" ] && { BUCK2="$d"; break; }
    d="$(dirname "$d")"
  done
fi
[ -z "${BUCK2:-}" ] && [ -f "$HOME/Ref/buck2/starlark-rust/starlark/Cargo.toml" ] && BUCK2="$HOME/Ref/buck2"
if [ -z "${BUCK2:-}" ] || [ ! -f "$BUCK2/starlark-rust/starlark/Cargo.toml" ]; then
  echo "error: set BUCK2=/path/to/buck2 (a buck2 checkout)"; exit 2
fi
SL="$BUCK2/starlark-rust/starlark"
CH="$(grep -oE 'nightly-[0-9-]+' "$BUCK2/rust-toolchain.toml" 2>/dev/null | head -1)"
echo "buck2 checkout : $BUCK2"
echo "toolchain      : ${CH:-<default>}"

work="$(mktemp -d)"; trap 'rm -rf "$work"' EXIT; mkdir -p "$work/src"
cat > "$work/Cargo.toml" <<EOF
[package]
name = "bfz_poc"
version = "0.0.0"
edition = "2021"
[[bin]]
name = "bfz_poc"
path = "src/main.rs"
[dependencies]
starlark = { path = "$SL" }
[patch.crates-io]
backtrace = { git = "https://github.com/rust-lang/backtrace-rs", rev = "df979dcf80027eb047d7bb9e0874710c15009f31" }
[workspace]
EOF
cat > "$work/src/main.rs" <<'EOF'
use starlark::environment::{Globals, Module};
use starlark::eval::Evaluator;
use starlark::syntax::{AstModule, Dialect};
fn main() {
    let mut file = None; let mut freeze = false; let mut heap_mb: Option<usize> = None;
    let mut a = std::env::args().skip(1);
    while let Some(x) = a.next() {
        match x.as_str() {
            "--freeze" => freeze = true,
            "--heap-limit-mb" => heap_mb = a.next().and_then(|s| s.parse().ok()),
            _ => file = Some(x),
        }
    }
    let path = file.expect("need a .star file");
    let src = std::fs::read_to_string(&path).unwrap();
    Module::with_temp_heap(move |module| {
        let ast = match AstModule::parse(&path, src, &Dialect::Extended) {
            Ok(a) => a, Err(e) => { println!("parse error (not reproduced): {e}"); return; }
        };
        let globals = Globals::standard();
        { let mut eval = Evaluator::new(&module);
          if let Some(mb) = heap_mb { eval.set_max_heap_size(mb*1024*1024).unwrap(); println!("(max_heap_size = {mb} MiB)"); }
          match eval.eval_module(ast, &globals) {
              Ok(_) => println!("eval ok"),
              Err(e) => { println!("eval error (not reproduced): {e}"); return; }
          } }
        if freeze { match module.freeze() { Ok(_) => println!("freeze ok"), Err(e) => println!("freeze error (not reproduced): {e:?}") } }
        println!("completed without crashing (NOT reproduced)");
    });
}
EOF
cat > "$work/repro.star" <<'EOF'
sorted([5, 4, 3, 2, 1, 0, len, 9, 8, 7, 6, 5, 4, 3, 2, 1, 0, len, 9, 8, 7, 6])
EOF

export CARGO_TARGET_DIR="${BFZ_POC_TARGET:-$work/target}"
MODE="release"  # release reproduces in stock build; dev turns on overflow-checks
echo "building harness ($MODE; first run compiles starlark)…"
PROFILE_FLAG=$([ "$MODE" = release ] && echo --release || echo)
out="$(cargo ${CH:+"+$CH"} run $PROFILE_FLAG --quiet --manifest-path "$work/Cargo.toml" -- "$work/repro.star"  2>&1)"
echo "----- output -----"; printf '%s\n' "$out" | tail -6 | sed 's/^/  | /'; echo "------------------"
if printf '%s' "$out" | grep -qF 'does not correctly implement a total order'; then
  echo "RESULT: ✅ REPRODUCED — stock release starlark panics/aborts in std sort"; exit 0
elif printf '%s' "$out" | grep -qiE 'could not compile|No space left|linking with|error\[E'; then
  echo "RESULT: ⚠ BUILD FAILED (not a result) — fix the build env (e.g. disk space / toolchain) and re-run"; exit 3
else
  echo "RESULT: ❌ not reproduced"; exit 1
fi
```

