```py
from collections.abc import Callable
from typing import Concatenate, overload, assert_type


class ClassAndInstanceMethod[T, **ClsParams, ClsResult, **SelfParams, SelfResult]:
    @overload
    def __get__(
        self, instance: T, owner: type[T]
    ) -> Callable[SelfParams, SelfResult]: ...
    @overload
    def __get__(
        self, instance: None, owner: type[T]
    ) -> Callable[ClsParams, ClsResult]: ...

    def __get__(
        self, instance: T | None, owner: type[T]
    ) -> Callable[ClsParams, ClsResult] | Callable[SelfParams, SelfResult]: ...


class A[T, **P, ClsResult, InstanceResult](
    ClassAndInstanceMethod[T, P, ClsResult, P, InstanceResult]
):
    def __init__(
        self, class_method: Callable[Concatenate[type[T], P], ClsResult]
    ) -> None: ...


class B[T, **P, R](A[T, P, type[R], R]): ...


class Foo:
    @B
    @classmethod
    def fn(cls) -> type[str]: ...


assert_type(Foo().fn(), str) # error, type is `Unknown`
assert_type(Foo.fn(), type[str]) # error, type is `type[Any]`
```

